<!DOCTYPE html>
<html>
<head>
  <title>Bouncing Ball Playground</title>
  <style>
    body {
      background-color: #1e1e1e;
      margin: 0;
      overflow: hidden;
    }

    #sim {
      width: 400px;
      height: 400px;
      border: 1px solid white;
      background-color: #282828;
      margin: 50px auto; /* Center the canvas */
      overflow: hidden;
    }

    button {
      background-color: #3e3e3e;
      border: none;
      color: white;
      padding: 10px 20px;
      text-align: center;
      text-decoration: none;
      display: inline-block;
      font-size: 16px;
      margin: 20px;
      cursor: pointer;
    }

    button:hover {
      background-color: #4e4e4e;
    }
  </style>
</head>
<body>
  <canvas id="sim"></canvas>
  <button id="drop">Drop Ball</button>
  <button id="play">Play</button>
  <button id="clear">Clear</button>

  <script>
    const canvas = document.getElementById('sim');
    const ctx = canvas.getContext('2d');
    window.sim = {
      w: canvas.width,
      h: canvas.height,
      balls: [],
      addBall(x, y, vx = 0, vy = 0, r = 10) {
        this.balls.push({ x, y, vx, vy, r });
      },
      clear() {
        this.balls = [];
      },
      step(dt = 1) {
        for (const ball of this.balls) {
          ball.vy += dt * 9.81; // Gravity

          // Bounce off floor
          if (ball.y + ball.r > this.h) {
            ball.y = this.h - ball.r;
            ball.vy *= -0.8; // Restitution (energy loss)
          }

          // Bounce off walls
          if (ball.x - ball.r < 0 || ball.x + ball.r > this.w) {
            ball.x = ball.r > this.w - ball.r ? this.w - ball.r : ball.r;
            ball.vx *= -1;
          }

          if (ball.y - ball.r < 0) {
            ball.y = ball.r;
            ball.vy *= -1;
          }
        }

        // Draw balls
        ctx.clearRect(0, 0, this.w, this.h);
        for (const ball of this.balls) {
          ctx.beginPath();
          ctx.arc(ball.x, ball.y, ball.r, 0, Math.PI * 2);
          ctx.fillStyle = '#6a5acd';
          ctx.fill();
          ctx.closePath();
        }
      },
    };

    let animating = false;

    document.getElementById('play').addEventListener('click', () => {
      animating = !animating;
      if (animating) {
        requestAnimationFrame(window.sim.step);
      }
    });

    document.getElementById('drop').addEventListener('click', () => {
      const x = Math.random() * (window.sim.w - 20);
      const y = Math.random() * (window.sim.h - 20);
      const vx = (Math.random() - 0.5) * 2; // Random velocity
      const vy = 0;
      window.sim.addBall(x, y, vx, vy);
    });

    document.getElementById('clear').addEventListener('click', () => {
      window.sim.clear();
    });


    // Add a ball on canvas click
    canvas.addEventListener('click', (e) => {
      const x = e.offsetX;
      const y = e.offsetY;
      window.sim.addBall(x, y);
    });

  </script>
</body>
</html>
